-- =============================================================================
-- University of Nigeria, Nsukka - Faculty of Science - Statistics
-- Course outlines transcribed from the departmental course handbook.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once.
--
-- NOTE ON SEMESTERS: the handbook does not state them; the usual Nigerian
-- odd/even course-number convention is applied. Correct in the Table Editor
-- where UNN differs.
--
-- NOTE ON CREDIT UNITS: the source PDF right-aligns unit values, so they were
-- extracted as a per-page block and matched back by page order. One to check
-- against the printed handbook: STA 384 (Report on Industrial Training) comes
-- out at 12 units, which is high for a report -- it may belong to STA 382
-- (Practical on Industrial Training), currently at 3.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Statistics';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('STA 111', 'Probability I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '100 Level', 'first', 2, 'Elementary set theory. Techniques of counting, sample space and Events. Basic notions of probability, definition, axioms and laws. Simple conditional probability and independence.', '["Elementary set theory", "Techniques of counting, sample space and Events", "Basic notions of probability, definition, axioms and laws", "Simple conditional probability and independence"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 112', 'Probability II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '100 Level', 'second', 2, 'One dimensional random variables, discrete and continuous: definition, moments and their distributions. Applications to Bernoulli, Binomial, Geometric, Poisson, Normal, Exponential and Hyper-geometric distributions.', '["One dimensional random variables, discrete and continuous: definition, moments and their distributions", "Applications to Bernoulli, Binomial, Geometric, Poisson, Normal, Exponential and Hyper-geometric distributions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 131', 'Inference I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '100 Level', 'first', 2, 'Statistical Data: sources, collection, presentation and analysis. Measures of central tendency and dispersion, skewness. Moments and kurtosis. Index numbers and demographic measures.', '["Statistical Data: sources, collection, presentation and analysis", "Measures of central tendency and dispersion, skewness", "Moments and kurtosis", "Index numbers and demographic measures"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 132', 'Inference II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '100 Level', 'second', 2, 'Elementary Time Series Analysis. Sampling and Statistical Inference: standard error and sampling distributions of the mean and proportion. Tests of significance for means and proportions. Simple linear regression and correlation.', '["Elementary Time Series Analysis", "Sampling and Statistical Inference: standard error and sampling distributions of the mean and proportion", "Tests of significance for means and proportions", "Simple linear regression and correlation"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 172', 'Statistical Computing I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '100 Level', 'second', 2, 'Generation of data using table of random numbers. Presentation and analysis of data. Computations using calculator involving measures of central tendency and dispersion, time series, index numbers, simple linear regression and correlation. Test of significance, one sample only.', '["Generation of data using table of random numbers", "Presentation and analysis of data", "Computations using calculator involving measures of central tendency and dispersion, time series, index numbers, simple linear regression and correlation", "Test of significance, one sample only"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 201', 'Statistics for Social Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'first', 2, 'Sources, collection, analysis and presentations of data. Index numbers, elementary analysis of time series, simple linear regression and correlation. Elementary non parametric tests.', '["Sources, collection, analysis and presentations of data", "Index numbers, elementary analysis of time series, simple linear regression and correlation", "Elementary non parametric tests"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 202', 'Statistics for Social Sciences II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'second', 2, 'Introductory probability. Binomial, Normal and Poisson distributions. Interval estimation and test of significance. Association of Attributes.', '["Introductory probability", "Binomial, Normal and Poisson distributions", "Interval estimation and test of significance", "Association of Attributes"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 203', 'Statistics for Agricultural and Biological Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'first', 2, 'Initial steps in planning of biological experiments. Methods of data collection, presentation and analysis. Measures of central tendency and dispersion. Frequency distributions. Elementary probability. Discrete and continuous distributions: Binomial, Poisson, Normal and exponential distributions. Interval estimation.', '["Initial steps in planning of biological experiments", "Methods of data collection, presentation and analysis", "Measures of central tendency and dispersion", "Frequency distributions", "Elementary probability", "Discrete and continuous distributions: Binomial, Poisson, Normal and exponential distributions", "Interval estimation"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 204', 'Statistics for Agricultural and Biological Sciences II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'second', 2, 'Tests of significance. Student $t$ test and $\chi^2$ test. Two sample test and paired comparison. Regression and correlation. Analysis of variance: one way, two way with no interaction. Latin square analysis. Multiple range tests. Analysis of covariance. Simple analysis of direct assays.', '["Tests of significance", "Student $t$ test and $\\chi^2$ test", "Two sample test and paired comparison", "Regression and correlation", "Analysis of variance: one way, two way with no interaction", "Latin square analysis", "Multiple range tests", "Analysis of covariance", "Simple analysis of direct assays"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 205', 'Statistics for Physical Sciences and Engineering I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'first', 2, 'Frequency Distributions. Elements of Probability. Discrete probability distributions: Binomial, Poisson, Geometric and Hyper-geometric. Continuous probability distributions: Normal, Student''s $t$, Chi-square $\chi^2$ and $F$. Combinatorial and moment generating functions.', '["Frequency Distributions", "Elements of Probability", "Discrete probability distributions: Binomial, Poisson, Geometric and Hyper-geometric", "Continuous probability distributions: Normal, Student''s $t$, Chi-square $\\chi^2$ and $F$", "Combinatorial and moment generating functions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 206', 'Statistics for Physical Sciences and Engineering II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'second', 2, 'Estimation: point and interval. Test of significance. Regression and correlation. Analysis of variance: one-way and two-way with no interaction.', '["Estimation: point and interval", "Test of significance", "Regression and correlation", "Analysis of variance: one-way and two-way with no interaction"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 211', 'Probability III', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'first', 2, 'Combinatorial analysis. Probability models for the study of random phenomena in finite sample spaces up to and including Bayes Theorem. Probability distribution of Discrete and Continuous two-dimensional random variables. Expectation and Univariate moment generating functions. Truncated distributions.', '["Combinatorial analysis", "Probability models for the study of random phenomena in finite sample spaces up to and including Bayes Theorem", "Probability distribution of Discrete and Continuous two-dimensional random variables", "Expectation and Univariate moment generating functions", "Truncated distributions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 212', 'Probability IV', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'second', 2, 'Tchebychev''s inequality. Normal approximation to Binomial distribution. Bivariate, marginal and conditional distributions and their moments. Convolution of two distributions.', '["Tchebychev''s inequality", "Normal approximation to Binomial distribution", "Bivariate, marginal and conditional distributions and their moments", "Convolution of two distributions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 231', 'Statistical Inference III', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'first', 3, 'Estimation: point estimation by method of moments, maximum likelihood and least square. Properties of estimators: Unbiasedness, Efficiency, Consistency, definition only. Interval Estimation: Confidence interval for proportions, means, variance and variance ratio. Test of significance: Tests based on normal, $t$, chi-square and $F$ distributions with regard to means, proportions, variance. Tests for independence of attributes and goodness-of-fit.', '["Estimation: point estimation by method of moments, maximum likelihood and least square", "Properties of estimators: Unbiasedness, Efficiency, Consistency, definition only", "Interval Estimation: Confidence interval for proportions, means, variance and variance ratio", "Test of significance: Tests based on normal, $t$, chi-square and $F$ distributions with regard to means, proportions, variance", "Tests for independence of attributes and goodness-of-fit"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 272', 'Statistical Computing II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '200 Level', 'second', 2, 'Use of computer software packages such as Minitab and Excel on probability and inference.', '["Use of computer software packages such as Minitab and Excel on probability and inference"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 311', 'Probability V', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 3, 'Probability Generating function. Bivariate Normal distribution: conditional and marginal densities, bivariate moment generating functions, characteristic function and inversion formula. Various modes of convergence. Central limit theorem. Elements of measure. Field of sets, fields, measure functions, probability measure and probability space. Introduction to Markov chains: basic concepts, state and parameter space, transition probabilities.', '["Probability Generating function", "Bivariate Normal distribution: conditional and marginal densities, bivariate moment generating functions, characteristic function and inversion formula", "Various modes of convergence", "Central limit theorem", "Elements of measure", "Field of sets, fields, measure functions, probability measure and probability space", "Introduction to Markov chains: basic concepts, state and parameter space, transition probabilities"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 321', 'Distribution Theory', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 2, 'Bivariate Normal Distribution, the gamma, chi-square, two types of Beta, $F$ and $t$ distributions. Distribution of functions of random variables: sums, products and quotients. Probability integral transformation. Order statistics and their functions.', '["Bivariate Normal Distribution, the gamma, chi-square, two types of Beta, $F$ and $t$ distributions", "Distribution of functions of random variables: sums, products and quotients", "Probability integral transformation", "Order statistics and their functions"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 323', 'Analysis of Variance', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 3, 'Analysis of one, double and multiple classifications of balanced data in crossed and nested arrangements. Analysis of two and three-way contingency tables for test of independence and interactions. Incomplete block designs. Log linear models. Analysis of covariance in one-way, two-way, three-way and nested classifications.', '["Analysis of one, double and multiple classifications of balanced data in crossed and nested arrangements", "Analysis of two and three-way contingency tables for test of independence and interactions", "Incomplete block designs", "Log linear models", "Analysis of covariance in one-way, two-way, three-way and nested classifications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 325', 'Biometrics I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 3, 'Direct Assays: types, nature and examples. Precision of estimates, Fieller''s theorem, dilution assays and design of direct assays. Indirect Assays: the dose response regression, condition of similarity and monotony. Linearizing transformations and non-linear regression. Parallel line assays: unsymmetrical designs, difference in preparations, potency estimation and fiducial limits and validity test. Approximate and exact analyses for missing entries. Symmetry design for parallel line assays. Efficiency, Reliability and Sensitivity.', '["Direct Assays: types, nature and examples", "Precision of estimates, Fieller''s theorem, dilution assays and design of direct assays", "Indirect Assays: the dose response regression, condition of similarity and monotony", "Linearizing transformations and non-linear regression", "Parallel line assays: unsymmetrical designs, difference in preparations, potency estimation and fiducial limits and validity test", "Approximate and exact analyses for missing entries", "Symmetry design for parallel line assays", "Efficiency, Reliability and Sensitivity"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 331', 'Inference IV', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 3, 'Criteria of Estimation: unbiasedness, consistency, efficiency, sufficiency and minimum variance, with proofs. Rao-Cramer Inequality. Testing of hypothesis: Null and alternative hypothesis, simple, composite hypothesis. Two types of error, critical region, Power size of a test, p-value, Neyman-Pearson Theorem. Most powerful test, and likelihood ratio test.', '["Criteria of Estimation: unbiasedness, consistency, efficiency, sufficiency and minimum variance, with proofs", "Rao-Cramer Inequality", "Testing of hypothesis: Null and alternative hypothesis, simple, composite hypothesis", "Two types of error, critical region, Power size of a test, p-value, Neyman-Pearson Theorem", "Most powerful test, and likelihood ratio test"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 341', 'Sampling Theory and Survey Methods I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 3, 'Basic sample selection procedures. Estimation of population mean, total and proportions in simple random sampling with and without replacement. Use of auxiliary information: ratio, regression and difference estimators. Stratification: Estimation of mean total population in stratified random sampling. Sample size allocation. Cluster sampling. Two stage Cluster sampling with clusters of equal sizes. Data collection in social investigations. Methods of social investigations. Planning of surveys. Methods of collecting information. Questionnaire design. Response errors, processing analysis and presentation of data.', '["Basic sample selection procedures", "Estimation of population mean, total and proportions in simple random sampling with and without replacement", "Use of auxiliary information: ratio, regression and difference estimators", "Stratification: Estimation of mean total population in stratified random sampling", "Sample size allocation", "Cluster sampling", "Two stage Cluster sampling with clusters of equal sizes", "Data collection in social investigations", "Methods of social investigations", "Planning of surveys", "Methods of collecting information", "Questionnaire design", "Response errors, processing analysis and presentation of data"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 343', 'Laboratory for Sampling and Survey Methods', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 2, 'Computations involving Stratification. Ratio and regression estimates, cluster and two stage sampling, Field Work.', '["Computations involving Stratification", "Ratio and regression estimates, cluster and two stage sampling, Field Work"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 345', 'Statistical Quality Control', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 3, 'Concept of quality and meaning of control. Specifications: Control limits and specifications, process spread and specifications. Control charts for variables and attributes: Determination of process capability and standard CuSuM charts. Acceptance sample inspection by attributes: single, double and multiple sampling plans.', '["Concept of quality and meaning of control", "Specifications: Control limits and specifications, process spread and specifications", "Control charts for variables and attributes: Determination of process capability and standard CuSuM charts", "Acceptance sample inspection by attributes: single, double and multiple sampling plans"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 347', 'Laboratory and Field Work for Quality Control I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 2, 'Practical construction of control charts. Computations involving tolerance limits, simple, multiple and sequential sampling plans. Use of the Poisson approximation to design sampling plans for the producers and consumers risk method. Design and analysis of various rectification schemes.', '["Practical construction of control charts", "Computations involving tolerance limits, simple, multiple and sequential sampling plans", "Use of the Poisson approximation to design sampling plans for the producers and consumers risk method", "Design and analysis of various rectification schemes"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 351', 'Demography', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 3, 'Sources of demographic data: Census and vital registration. Rates and ratios. Study of mortality. Construction of Life tables. Expectation of life. Measure of fertility and morbidity. Population growth and projection. Migration and the population distribution: interpretation of population parameters from defective data. Stable and quasi stable populations.', '["Sources of demographic data: Census and vital registration", "Rates and ratios", "Study of mortality", "Construction of Life tables", "Expectation of life", "Measure of fertility and morbidity", "Population growth and projection", "Migration and the population distribution: interpretation of population parameters from defective data", "Stable and quasi stable populations"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 353', 'Laboratory and Field Work for Demography', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 2, 'Computations involving mortality and fertility rates, life tables and population growth.', '["Computations involving mortality and fertility rates, life tables and population growth"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 357', 'Actuarial Statistics I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 2, 'Effective rate of interest, Normal rate of interest, Force of interest. Relationship between $i$, $i^{(m)}$ and Present Value. Elective and normal rate of Discount. Present value of immediate Annuity, annuity due, increasing and decreasing Annuities, Continuous Annuity. Accumulation of Annuities increasing by step and continuously. Repayment of loan by equated installments: Annuity and Sinking funds. Capital and Interest Element contained in the $t$-th installment. Purchase price of annuities, net of Tax-Loan Schedules.', '["Effective rate of interest, Normal rate of interest, Force of interest", "Relationship between $i$, $i^{(m)}$ and Present Value", "Elective and normal rate of Discount", "Present value of immediate Annuity, annuity due, increasing and decreasing Annuities, Continuous Annuity", "Accumulation of Annuities increasing by step and continuously", "Repayment of loan by equated installments: Annuity and Sinking funds", "Capital and Interest Element contained in the $t$-th installment", "Purchase price of annuities, net of Tax-Loan Schedules"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 361', 'Algebraic Basis for Statistics', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 2, 'Vectors: Norms, scalar and cross products. Vector spaces: Basis and dimension. Matrices: elementary operation with matrices and vectors, rank, determinants, linear equations, orthogonality. Bilinear and quadratic forms, eigensystem. Differentiation with vector and matrices.', '["Vectors: Norms, scalar and cross products", "Vector spaces: Basis and dimension", "Matrices: elementary operation with matrices and vectors, rank, determinants, linear equations, orthogonality", "Bilinear and quadratic forms, eigensystem", "Differentiation with vector and matrices"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 363', 'Operations Research I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 3, 'The Nature of Operations Research: History, meaning and models. Classical methods of optimization: maxima and minima, Lagrange''s Multipliers, Convex set and functions. Linear Programming: formulation and Analysis using graphs. Simplex and revised simplex methods. Duality Theory and Applications. Sensitivity Analysis in Linear Programming.', '["The Nature of Operations Research: History, meaning and models", "Classical methods of optimization: maxima and minima, Lagrange''s Multipliers, Convex set and functions", "Linear Programming: formulation and Analysis using graphs", "Simplex and revised simplex methods", "Duality Theory and Applications", "Sensitivity Analysis in Linear Programming"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 365', 'Laboratory for Operations Research I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 2, 'Problem formulation involving linear programming applications. Computations involving simplex and revised simplex algorithms, graphs.', '["Problem formulation involving linear programming applications", "Computations involving simplex and revised simplex algorithms, graphs"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 371', 'Statistical Computing III', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'first', 2, 'Use of computer packages such as GENSTAT and SPSS and other current packages on topics in Inference IV, ANOVA, Operations Research, Regression and many other applicable areas.', '["Use of computer packages such as GENSTAT and SPSS and other current packages on topics in Inference IV, ANOVA, Operations Research, Regression and many other applicable areas"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 382', 'Practical on Industrial Training', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'second', 3, 'Practical work engaged in during the Industrial Training.', '["Practical work engaged in during the Industrial Training"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 384', 'Report on Industrial Training', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '300 Level', 'second', 12, 'Report to be presented after the Industrial Training.', '["Report to be presented after the Industrial Training"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 411', 'Probability VII', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'first', 3, 'Probability spaces, measures and distributions. Product spaces: product of measurable spaces, product probabilities. Random variables as measurable functions. Independence and expectations of product random variables. Convergence of random variables: Weak convergence, convergence almost everywhere, convergence in $p$-th mean. Central Limit Theorem. Characteristic function and Laplace transforms. Inversion formula.', '["Probability spaces, measures and distributions", "Product spaces: product of measurable spaces, product probabilities", "Random variables as measurable functions", "Independence and expectations of product random variables", "Convergence of random variables: Weak convergence, convergence almost everywhere, convergence in $p$-th mean", "Central Limit Theorem", "Characteristic function and Laplace transforms", "Inversion formula"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 413', 'Stochastic Processes I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'first', 2, 'Random walk: simple and general random walk with absorbing and reflecting barriers. Markovian processes with finite chains. Branching processes, Poisson process, relevant applications.', '["Random walk: simple and general random walk with absorbing and reflecting barriers", "Markovian processes with finite chains", "Branching processes, Poisson process, relevant applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 414', 'Stochastic Processes II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'second', 2, 'Birth and Death Processes. Queuing Processes: M/M/1, M/M/S, M/C and G/M/1 Queues and their waiting time distributions. Diffusion Process. Relevant applications.', '["Birth and Death Processes", "Queuing Processes: M/M/1, M/M/S, M/C and G/M/1 Queues and their waiting time distributions", "Diffusion Process", "Relevant applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 415', 'Time Series I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'first', 2, 'Components of Time Series, measurement of trend, the seasonal index, the cyclical component and random fluctuations, serial correlation, Correlogram.', '["Components of Time Series, measurement of trend, the seasonal index, the cyclical component and random fluctuations, serial correlation, Correlogram"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 416', 'Time Series II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'second', 2, 'Stationary Time Series: Second order Stationarity, the autocorrelation function. Autoregressive process, Moving Average Processes of mixed models. Integrated Models. Estimation of the Parameters, Forecasting and Spectral density.', '["Stationary Time Series: Second order Stationarity, the autocorrelation function", "Autoregressive process, Moving Average Processes of mixed models", "Integrated Models", "Estimation of the Parameters, Forecasting and Spectral density"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 421', 'Design and Analysis of Experiment I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'first', 2, 'Meaning, Need, Purpose and Basic Principles of Experimental Design. Efficient design: Randomization, replication and blocking, local control. Basic designs: Completely randomized design (CRD), Randomized complete block design (RCBD), Latin square design. Relative efficiency, missing values. Multiple comparisons. Departures from underlying assumptions and examples from agriculture, biology and industry.', '["Meaning, Need, Purpose and Basic Principles of Experimental Design", "Efficient design: Randomization, replication and blocking, local control", "Basic designs: Completely randomized design (CRD), Randomized complete block design (RCBD), Latin square design", "Relative efficiency, missing values", "Multiple comparisons", "Departures from underlying assumptions and examples from agriculture, biology and industry"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 422', 'Design and Analysis of Experiment II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'second', 2, 'BIB designs, and factorial experiments. Split-plot design. Expected mean square (EMS) rules, $2^n$ factorial designs: Yates algorithm, confounding, fractional replication. Applications with real life data. Introduction to response surface methodology.', '["BIB designs, and factorial experiments", "Split-plot design", "Expected mean square (EMS) rules, $2^n$ factorial designs: Yates algorithm, confounding, fractional replication", "Applications with real life data", "Introduction to response surface methodology"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 423', 'Regression Analysis', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'first', 3, 'Simple linear and multiple regression. Inference on regression parameters. Polynomial regression. Examination of residuals, use of dummy variable. Reparametrization of non-linear models. Partial, total and multiple correlation ratio. Generalized least squares. Prediction from regression. Multicollinearity, autocorrelation and Heteroscedasticity: Durbin-Watson test, Outliers, Selection of the best regression equation. Simple treatment of logistic regression.', '["Simple linear and multiple regression", "Inference on regression parameters", "Polynomial regression", "Examination of residuals, use of dummy variable", "Reparametrization of non-linear models", "Partial, total and multiple correlation ratio", "Generalized least squares", "Prediction from regression", "Multicollinearity, autocorrelation and Heteroscedasticity: Durbin-Watson test, Outliers, Selection of the best regression equation", "Simple treatment of logistic regression"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 425', 'Biometrics II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'first', 2, 'Slope ratio assays: the power dose metameter, multiple regression equation. Analysis of variance and validity tests. Symmetrical $(2K+1)$ point design. Comparison of assay techniques.', '["Slope ratio assays: the power dose metameter, multiple regression equation", "Analysis of variance and validity tests", "Symmetrical $(2K+1)$ point design", "Comparison of assay techniques"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 426', 'Biometrics III', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'second', 2, 'Multiple assays: economy of multiple assays, multiple slope ratio assays and Design of multiple assays. Distribution of responses between preparations. Composite responses, the discriminant problem, examples of an assay using a Discriminant function; discriminants and concomitants; the economies of Discriminant analysis.', '["Multiple assays: economy of multiple assays, multiple slope ratio assays and Design of multiple assays", "Distribution of responses between preparations", "Composite responses, the discriminant problem, examples of an assay using a Discriminant function; discriminants and concomitants; the economies of Discriminant analysis"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 431', 'Bayesian Inference I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'first', 2, 'Bayes'' theorem. Posterior distributions. Point estimation with the loss functions. Squared error loss, absolute error loss and zero one loss. Interval estimation, shortest, highest posterior density (HPD), equal tail and one tail interval, prediction of a future observation. Choice of prior: natural conjugate family of priors (NCP) and non-informative priors (NIP). Application to some standard one and two-parameter problems.', '["Bayes'' theorem", "Posterior distributions", "Point estimation with the loss functions", "Squared error loss, absolute error loss and zero one loss", "Interval estimation, shortest, highest posterior density (HPD), equal tail and one tail interval, prediction of a future observation", "Choice of prior: natural conjugate family of priors (NCP) and non-informative priors (NIP)", "Application to some standard one and two-parameter problems"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 432', 'Bayesian Inference II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'second', 2, 'Comparison of the means and variances of two normal and two Poisson distributions. Linear regression: joint and marginal posterior distributions of regression parameters for normally distributed regressor variables. Tests of hypothesis: Jeffrey''s methods and decision theoretic approach. Applications.', '["Comparison of the means and variances of two normal and two Poisson distributions", "Linear regression: joint and marginal posterior distributions of regression parameters for normally distributed regressor variables", "Tests of hypothesis: Jeffrey''s methods and decision theoretic approach", "Applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 433', 'Multivariate Analysis I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'first', 2, 'The multivariate normal distribution: definition, generating function, conditional distribution of the estimates. The Hotelling''s distribution, Wishart distribution. Inference about mean vectors: one sample and two sample cases. Tests of independence.', '["The multivariate normal distribution: definition, generating function, conditional distribution of the estimates", "The Hotelling''s distribution, Wishart distribution", "Inference about mean vectors: one sample and two sample cases", "Tests of independence"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 434', 'Multivariate Analysis II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'second', 2, 'Classification: the linear discriminant function for two groups, errors of Misclassification and estimation of misclassification probabilities. Principal components: meaning, computation and interpretation; sampling properties. Factor analysis: model for factor structure, estimation of factor loadings, factor rotation applications.', '["Classification: the linear discriminant function for two groups, errors of Misclassification and estimation of misclassification probabilities", "Principal components: meaning, computation and interpretation; sampling properties", "Factor analysis: model for factor structure, estimation of factor loadings, factor rotation applications"]'::jsonb, 'Department of Statistics handbook'),
  ('STA 435', 'Non-Parametric Methods I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Statistics', '400 Level', 'first', 2, 'Nonparametric versus parametric inference. Distribution-free Statistics. Order Statistics.', '["Nonparametric versus parametric inference", "Distribution-free Statistics", "Order Statistics"]'::jsonb, 'Department of Statistics handbook'),
